using System.ComponentModel.DataAnnotations;namespace Data.Models;public class SourceCountryModel{    public string _id { get; set; }    [Display(Name = "Source Country Id")] public int SOURCE_COUNTRY_ID { get; set; }    [Display(Name = "Region Name")] public string REGION_NAME { get; set; }    [Display(Name = "Geo Code")]    [Required(ErrorMessage = "Empty Geo Code")]    [RegularExpression(@"^(\d{3})$", ErrorMessage = "Please enter 3 digit number")]    public string GEO_CODE { get; set; }    [Display(Name = "Name Old")] public string NAME_OLD { get; set; }    [Display(Name = "Short Legend")] public string SHORT_LEGEND { get; set; }    [Display(Name = "Long Legend")] public string LONG_LEGEND { get; set; }    [Display(Name = "Active")]    [Required(ErrorMessage = "Please select Active status")]    public string ACTIVE { get; set; }    [Display(Name = "Frequency")] public string FREQUENCY { get; set; }    [DataType(DataType.Date)] public DateTime LATEST_DATE { get; set; }    [DataType(DataType.Date)] public DateTime FIRST_DATE { get; set; }    [Display(Name = "Side of Trade")] public string SIDE_OF_TRADE { get; set; }    [Display(Name = "Currency Code")] public string CURRENCY_CODE { get; set; }    [Display(Name = "Data Format")] public string DATA_FORMAT { get; set; }    [Display(Name = "Old Geo Code")] public string OLD_GEO_CODE { get; set; }    [DataType(DataType.Date)] public DateTime GEO_CODE_DISCONTINUED_DATE { get; set; }    [Display(Name = "Industry Reporting Centre ID")]    public int INDUSTRY_REPORTING_CENTRE_ID { get; set; }    [Display(Name = "Name")] public string NAME { get; set; }}public class SourceCountryJsonModel{    public List<SourceCountryModel> Countries { get; set; }}